import { auth } from "../firebase.js";

const EXPORT_URL = "/api/integrations/export";

// The PDF is generated by Student Docs using the verified spreadsheet row.
// No payment totals, draft data, webhook secret or PDF bytes enter audit logs.
export async function downloadStudentDocumentPdf({ studentCode, email, kind }) {
  const current = auth?.currentUser;
  if (!current) throw new Error("Please sign in again before exporting a student document.");
  if (!["enrollment", "agreement"].includes(kind)) throw new Error("Select a valid PDF type.");
  if (!String(studentCode || "").trim() && !String(email || "").trim()) {
    throw new Error("The student needs a verified code or email.");
  }
  const response = await fetch(EXPORT_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${await current.getIdToken()}`,
    },
    cache: "no-store",
    body: JSON.stringify({
      document_type: kind,
      student_code: String(studentCode || "").trim(),
      email: String(email || "").trim(),
    }),
  });
  const result = await response.json().catch(() => ({}));
  if (!response.ok || result.ok !== true) {
    throw new Error(result.error || "The Student Docs PDF export failed.");
  }
  const encoded = String(result.data_base64 || "");
  if (result.mime_type !== "application/pdf" || !encoded || encoded.length > 4_000_000) {
    throw new Error("The document server returned an invalid PDF.");
  }
  const binary = atob(encoded);
  if (!binary.startsWith("%PDF-")) throw new Error("The document server did not return PDF data.");
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  const blob = new Blob([bytes], { type: "application/pdf" });
  const fileName = String(result.file_name || `falowen-${kind}.pdf`)
    .replace(/[^a-zA-Z0-9._-]/g, "_").slice(0, 150);
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName.endsWith(".pdf") ? fileName : fileName + ".pdf";
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  return fileName;
}
